/**
 * @amc/assets: canonical brand SVG renderers, byte-for-byte with
 * `services/langgraph/agency/assets.py` (Python is the reference).
 * `tests/fixtures/assets-parity.json` and `src/python-unicode.ts` are
 * generated by `services/langgraph/tests/test_assets_parity_fixture.py`.
 *
 * Each renderer builds the same text Python's f-string builds (eight-space
 * indent, values interpolated before dedent) and then runs Python's
 * `textwrap.dedent`, so a value containing a newline shifts the output exactly
 * as it does in Python. Colours are interpolated unescaped, as in Python.
 *
 * Initials follow Python's `str.split()` (Python's whitespace set, not JS
 * `\s`), take the first code point (not UTF-16 unit) and apply full Unicode
 * uppercasing only to code points Python's Unicode version can uppercase.
 */
import { pyDedent } from './dedent';
import { PYTHON_UNIDATA_VERSION, SPACE_RANGES, UPPER_CASED_RANGES, type CodePointRange } from './python-unicode';

export { PYTHON_UNIDATA_VERSION, pyDedent };

export interface LogoOptions {
  readonly brandName: string;
  readonly primary: string;
  readonly secondary: string;
  readonly surface: string;
  readonly tagline?: string | null;
}

export interface PatternOptions {
  readonly brandName: string;
  readonly primary: string;
  readonly secondary: string;
  readonly surface: string;
}

export interface HeroOptions extends PatternOptions {
  readonly headline: string;
  readonly audience: string;
  readonly accent: string;
}

const DEFAULT_TAGLINE = 'geometric mark · canonical render';
const FONT = 'Inter, Arial, sans-serif';

function cp(codePoint: number): string {
  return `\\u{${codePoint.toString(16)}}`;
}

function classBody(ranges: readonly CodePointRange[]): string {
  return ranges.map(([lo, hi]) => (lo === hi ? cp(lo) : `${cp(lo)}-${cp(hi)}`)).join('');
}

const PY_WHITESPACE_RUN = new RegExp(`[${classBody(SPACE_RANGES)}]+`, 'u');

function isPythonCased(char: string): boolean {
  const code = char.codePointAt(0) ?? -1;
  return UPPER_CASED_RANGES.some(([lo, hi]) => code >= lo && code <= hi);
}

/** Python `part[:1].upper()`: first code point, uppercased only where Python can. */
function pyFirstUpper(part: string): string {
  const first = Array.from(part)[0] ?? '';
  return isPythonCased(first) ? first.toUpperCase() : first;
}

/** Python `"".join(p[:1].upper() for p in brand_name.split()[:2]) or "B"`. */
export function initials(brandName: string): string {
  const parts = brandName.split(PY_WHITESPACE_RUN).filter((part) => part.length > 0);
  return parts.slice(0, 2).map(pyFirstUpper).join('') || 'B';
}

/** XML text/attribute escaping, same replacements in the same order as Python's `_escape`. */
export function escapeXml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

/** The f-string body as Python sees it before dedent: eight-space indent and an indented closing line. */
function pyIndentedTemplate(lines: readonly string[]): string {
  return lines.map((line) => `        ${line}`).join('\n') + '\n        ';
}

export function renderLogoSvg(o: LogoOptions): string {
  const safeName = escapeXml(o.brandName);
  const safeTagline = escapeXml(o.tagline || DEFAULT_TAGLINE);
  return pyDedent(
    pyIndentedTemplate([
      `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200" role="img" aria-label="${safeName} logo mark">`,
      `  <rect width="1200" height="1200" rx="240" fill="${o.surface}"/>`,
      `  <circle cx="600" cy="600" r="360" fill="${o.secondary}" opacity="0.15"/>`,
      `  <path d="M300 840 L600 240 L900 840 Z" fill="${o.primary}"/>`,
      `  <circle cx="600" cy="610" r="110" fill="${o.surface}"/>`,
      `  <text x="600" y="645" text-anchor="middle" font-family="${FONT}" font-size="140" font-weight="700" fill="${o.primary}">${escapeXml(initials(o.brandName))}</text>`,
      `  <text x="600" y="1030" text-anchor="middle" font-family="${FONT}" font-size="44" letter-spacing="6" fill="${o.primary}">${safeTagline}</text>`,
      '</svg>',
    ]),
  );
}

const PATTERN_WAVES = [
  'M0 180 C200 60 400 60 600 180 S1000 300 1200 180 S1400 60 1600 180',
  'M0 450 C200 330 400 330 600 450 S1000 570 1200 450 S1400 330 1600 450',
  'M0 720 C200 600 400 600 600 720 S1000 840 1200 720 S1400 600 1600 720',
];

const PATTERN_DOTS = [
  [220, 180, 56],
  [780, 450, 72],
  [1320, 720, 64],
  [1180, 180, 40],
  [420, 720, 48],
] as const;

export function renderBackgroundPatternSvg(o: PatternOptions): string {
  return pyDedent(
    pyIndentedTemplate([
      `<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900" role="img" aria-label="${escapeXml(o.brandName)} background pattern">`,
      `  <rect width="1600" height="900" fill="${o.surface}"/>`,
      `  <g fill="none" stroke="${o.primary}" stroke-width="6" opacity="0.18">`,
      ...PATTERN_WAVES.map((d) => `    <path d="${d}"/>`),
      '  </g>',
      `  <g fill="${o.secondary}" opacity="0.12">`,
      ...PATTERN_DOTS.map(([cx, cy, r]) => `    <circle cx="${cx}" cy="${cy}" r="${r}"/>`),
      '  </g>',
      '</svg>',
    ]),
  );
}

function heroTexts(o: HeroOptions): string[] {
  return [
    `  <text x="144" y="268" font-family="${FONT}" font-size="88" font-weight="700" fill="${o.primary}">${escapeXml(o.headline)}</text>`,
    `  <text x="144" y="350" font-family="${FONT}" font-size="32" fill="${o.primary}" opacity="0.82">Built for ${escapeXml(o.audience)}</text>`,
    `  <text x="144" y="760" font-family="${FONT}" font-size="28" fill="${o.primary}" opacity="0.62">${escapeXml(o.brandName)} · canonical brand render</text>`,
  ];
}

function heroDefs(o: HeroOptions): string[] {
  return [
    '  <defs>',
    '    <linearGradient id="hero-bg" x1="0" y1="0" x2="1" y2="1">',
    `      <stop offset="0%" stop-color="${o.surface}"/>`,
    `      <stop offset="100%" stop-color="${o.accent}"/>`,
    '    </linearGradient>',
    '  </defs>',
  ];
}

export function renderHeroSvg(o: HeroOptions): string {
  return pyDedent(
    pyIndentedTemplate([
      `<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900" role="img" aria-label="${escapeXml(o.brandName)} hero illustration">`,
      ...heroDefs(o),
      '  <rect width="1600" height="900" fill="url(#hero-bg)"/>',
      `  <rect x="108" y="108" width="640" height="684" rx="42" fill="${o.primary}" opacity="0.08"/>`,
      `  <rect x="820" y="108" width="672" height="320" rx="42" fill="${o.secondary}" opacity="0.18"/>`,
      `  <rect x="820" y="468" width="320" height="324" rx="42" fill="${o.primary}" opacity="0.16"/>`,
      `  <rect x="1172" y="468" width="320" height="324" rx="42" fill="${o.secondary}" opacity="0.10"/>`,
      ...heroTexts(o),
      '</svg>',
    ]),
  );
}
